using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF9: Default discriminator property renamed from "Discriminator" to "$type".
            // Existing 500K documents use "Discriminator" — preserve for compatibility.
            entity.HasDiscriminator<string>("Discriminator");

            // EF9: id no longer includes discriminator prefix (was "Product|123", now "123").
            // Existing documents have the compound format — preserve for point-reads to work.
            entity.HasRootDiscriminatorInJsonId(true);
        });

        // REMOVED: HasIndex throws at startup in EF Core 9 Cosmos provider.
        // Cosmos DB indexing is managed via the container's indexing policy (Azure Portal/Bicep).
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

